output_text:
[
  {
    "id": "must_checkout_cart",
    "text": "At the start of a shopping trip, the shopper is obliged to take the cart from the entrance cart station at (1,5).",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": "at(1,5)",
        "entrance_cart_available": "cartAt(1,5)",
        "ready_to_take_entrance_cart": {
          "and": [
            "at_entrance_cart_station",
            "entrance_cart_available"
          ]
        }
      },
      "events": {
        "checkout_cart": {
          "pre": {
            "and": [
              "ready_to_take_entrance_cart",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "checkout_cart"
    }
  },
  {
    "id": "must_return_checked_out_cart",
    "text": "After taking a cart, the shopper is obliged to return it to the cart-return bay at (0,1) before leaving.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": "at(1,5)",
        "entrance_cart_available": "cartAt(1,5)",
        "at_cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "checkout_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_station",
              "entrance_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "at_cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "checkout_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_abandon_cart_outside_return",
    "text": "A cart may not be left behind anywhere except the designated return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "at_cart_return_bay": "at(0,1)",
        "outside_cart_return_bay": {
          "not": "at_cart_return_bay"
        }
      },
      "events": {
        "leave_cart_outside_return": {
          "pre": {
            "and": [
              "hasCart",
              "LEAVE_CART",
              "outside_cart_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "The shopper is prohibited from taking a shopping cart through the store exit.",
    "abstraction": {
      "state_properties": {
        "at_exit": "at(9,5)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "at_exit",
              "pushing_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "items_must_go_in_cart",
    "text": "Shelf items must be picked up only while the shopper is pushing a cart, rather than being collected without one.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "not_pushing_cart": {
          "not": "pushing_cart"
        }
      },
      "events": {
        "uncarted_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "not_pushing_cart"
            ]
          },
          "post": null
        },
        "carted_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "uncarted_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "The shopper is prohibited from carrying groceries by hand at any point in the trip.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {
        "become_hand_full": {
          "pre": "PICKUP_ITEM",
          "post": "carrying_item_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "return_cart_after_item_pickup",
    "text": "Once any required item has been picked up into the cart, the shopper is obliged eventually to park the cart at the return bay.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "at_cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "carted_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "pushing_cart"
            ]
          },
          "post": null
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "at_cart_return_bay",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "carted_item_pickup",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "egg_shelf_cart_turnback",
    "text": "After collecting an item from the egg-shelf service position at (6,4) while using a cart, the shopper is obliged to turn back west from that position rather than continue east with the cart.",
    "abstraction": {
      "state_properties": {
        "at_egg_shelf_position": "at(6,4)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "pick_item_at_egg_shelf_with_cart": {
          "pre": {
            "and": [
              "at_egg_shelf_position",
              "pushing_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "turn_west_from_egg_shelf_with_cart": {
          "pre": {
            "and": [
              "at_egg_shelf_position",
              "pushing_cart",
              "W"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pick_item_at_egg_shelf_with_cart",
      "discharge": "turn_west_from_egg_shelf_with_cart"
    }
  }
]
